const [ready, setReady] = useState(false);
const [target, setTarget] = useState(() => Date.now() + 30_000);

{ready ? (
  <Button variant="outline" onPress={() => { setReady(false); setTarget(Date.now() + 30_000); }}>
    Resend code
  </Button>
) : (
  <Countdown to={target} variant="inline" size="sm" units={['minutes', 'seconds']} onComplete={() => setReady(true)} />
)}

