const [ends] = useState(() => Date.now() + 308_000);
const [over, setOver] = useState(false);

<Card>
  <Card.Header>
    <View className="flex-row items-center justify-between gap-3">
      <Badge>Flash sale</Badge>
      {over ? (
        <Text size="sm" weight="semibold" muted>Ended</Text>
      ) : (
        <View className="flex-row items-baseline gap-1.5">
          <Text size="sm" muted>Ends in</Text>
          <Countdown
            to={ends}
            variant="inline"
            size="sm"
            units={["minutes", "seconds"]}
            urgentBelow={300}
            onComplete={() => setOver(true)}
          />
        </View>
      )}
    </View>
    <Card.Title>40% off every annual plan</Card.Title>
  </Card.Header>
</Card>

const [target, setTarget] = useState(() => Date.now() + 30_000);
const [ready, setReady] = useState(false);

<OtpInput length={6} groupEvery={3} />
{ready ? (
  <Button
    variant="outline"
    onPress={() => {
      setReady(false);
      setTarget(Date.now() + 30_000);
    }}
  >
    Resend code
  </Button>
) : (
  <View className="flex-row items-baseline justify-center gap-1.5">
    <Text size="sm" muted>Resend a code in</Text>
    <Countdown
      to={target}
      variant="inline"
      size="sm"
      units={["minutes", "seconds"]}
      onComplete={() => setReady(true)}
    />
  </View>
)}
